mapper.select:
SELECT COUNT(1)
FROM order_delay_apply a
JOIN dept_work_order w ON w.id = a.order_id
WHERE a.status = 'PENDING' AND w.is_deleted = 0
AND w.category = #{department}
AND w.county_code = #{countyCode}

mapper.update:
UPDATE order_delay_apply
SET status = #{status}, approve_user_id = #{approveUserId}, approve_time = #{approveTime},
    approve_remark = #{approveRemark}
WHERE id = #{id}
